WITH RECURSIVE ${tree} AS (
  SELECT ${id}, ${parent}, 1 AS depth FROM ${table} WHERE ${id} = ${start}
  UNION ALL
  SELECT t.${id}, t.${parent}, ${tree}.depth + 1 FROM ${table} t JOIN ${tree} ON t.${id} = ${tree}.${parent}
)
SELECT * FROM ${tree}

SELECT ${order_column}, ${value_column},
  SUM(${value_column}) OVER (ORDER BY ${order_column} ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
FROM ${table}
ORDER BY ${order_column}

SELECT p.*, l.*
FROM ${parent} p
JOIN LATERAL (
  SELECT c.* FROM ${child} c WHERE c.${foreign_key} = p.${parent_key} ORDER BY c.${order_column} DESC LIMIT ${n}
) l ON TRUE
